const DEFAULT_PACKET_BUFFER_SIZE : usize = 2048 ; pub const PACKET_BUFFER_SIZE : usize = match option_env ! ("PACKET_BUFFER_SIZE") { None => DEFAULT_PACKET_BUFFER_SIZE , Some (num_str) => { match num_str . parse :: < usize > () { Ok (num) => { match num . is_power_of_two () { true => num , _ => DEFAULT_PACKET_BUFFER_SIZE , } } , _ => { DEFAULT_PACKET_BUFFER_SIZE } , } } } ; fn main () { println ! ("{}" , DEFAULT_PACKET_BUFFER_SIZE) ; }